def copy_past_changes(apps, schema_editor):
    """Status changes made before this table existed are in the audit log: copy them, so the
    bed board shows each bed's history from the start."""
    AuditEvent = apps.get_model("audit", "AuditEvent")
    Bed = apps.get_model("beds", "Bed")
    BedStatusChange = apps.get_model("beds", "BedStatusChange")
    User = apps.get_model("identity", "User")
    beds = {str(bed.pk): bed for bed in Bed.objects.all()}
    users = set(User.objects.values_list("pk", flat=True))
    rows = []
    for event in AuditEvent.objects.filter(
        action="bed.status.changed", resource_type="bed"
    ).order_by("occurred_at"):
        bed = beds.get(event.resource_id)
        before = (event.changes or {}).get("before", {}).get("status")
        after = (event.changes or {}).get("after", {}).get("status")
        if bed is None or not before or not after:
            continue
        rows.append(
            BedStatusChange(
                bed_id=bed.pk,
                facility_id=bed.facility_id,
                ward_id=bed.ward_id,
                from_status=before,
                to_status=after,
                reason=(event.reason or "")[:255],
                changed_by_id=event.actor_id if event.actor_id in users else None,
                changed_at=event.occurred_at,
            )
        )
    BedStatusChange.objects.bulk_create(rows, batch_size=500)


